import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputStr = scanner.next();
        int totalLength = inputStr.length();
        boolean firstReplacementDone = true;
        StringBuilder output = new StringBuilder();

        int index = 0;
        while (index < totalLength) {
            if (index + 1 < totalLength && inputStr.charAt(index) == 'a' && inputStr.charAt(index + 1) == 't' && firstReplacementDone && index != 0 && index != totalLength - 2) {
                output.append('@');
                firstReplacementDone = false;
                index++;
            } else if (index + 2 < totalLength && inputStr.charAt(index) == 'd' && inputStr.charAt(index + 1) == 'o' && inputStr.charAt(index + 2) == 't' && index != 0 && index != totalLength - 3) {
                output.append('.');
                index += 2;
            } else {
                output.append(inputStr.charAt(index));
            }
            index++;
        }

        System.out.println(output.toString());
        scanner.close();
    }
}
